payload.text:
To fulfill your request, I will make the following changes to the application:

1.  **Restrict IC Number**: Enforce numeric-only input for the IC field in the visitor form.
2.  **Add Car Plate Field**: Introduce a new input field for "Car Plate Number" in the visitor registration form, which automatically converts input to uppercase.
3.  **Update Data Structures**: Modify `VisitorData` and `SecurityLog` types to include `carPlate`.
4.  **Enhance Guard Dashboard & Logs**: Display the car plate number in the guard's scanning terminal and the visitor logs history (including CSV export).
5.  **Update AI Prompt**: Ensure the car plate is included in the AI-generated security log.

Here are the updated files:

# Updated files:

## types.ts

Added `carPlate` to both `VisitorData` and `SecurityLog` interfaces.

```typescript

export interface VisitorData {
  fullName: string;
  phoneNumber: string;
  icNumber: string;
  carPlate: string;
  blockNumber: string;
  lotNumber: string;
  timestamp: number; // Unix timestamp for creation
}

export interface SecurityLog {
  id: string;
  visitorName: string;
  icNumber: string;
  carPlate?: string;
  destination: string;
  checkInTime: string;
  status: 'GRANTED' | 'DENIED' | 'EXPIRED';
  aiAnalysis: string;
}

export enum AppMode {
  HOME = 'HOME',
  VISITOR = 'VISITOR',
  GUARD = 'GUARD',
  PRESENTATION = 'PRESENTATION'
}
```

## components/VisitorForm.tsx

Added the Car Plate input field, implemented strict digit-only validation for IC numbers, and auto-uppercasing for car plates.

```tsx
import React, { useState } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { VisitorData } from '../types';
import { User, Phone, MapPin, Building, CreditCard, ArrowLeft, Download, CheckCircle, Car } from 'lucide-react';

interface VisitorFormProps {
  onBack: () => void;
}

const VisitorForm: React.FC<VisitorFormProps> = ({ onBack }) => {
  const [formData, setFormData] = useState<Partial<VisitorData>>({
    fullName: '',
    phoneNumber: '',
    icNumber: '',
    carPlate: '',
    blockNumber: '',
    lotNumber: ''
  });
  const [generatedQR, setGeneratedQR] = useState<string | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;

    if (name === 'icNumber') {
      // STRICT: Only allow digits (0-9). Remove any non-digit character.
      const numericValue = value.replace(/\D/g, '');
      setFormData(prev => ({ ...prev, [name]: numericValue }));
    } else if (name === 'carPlate') {
      // Auto-uppercase for car plates
      setFormData(prev => ({ ...prev, [name]: value.toUpperCase() }));
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const payload: VisitorData = {
      fullName: formData.fullName!,
      phoneNumber: formData.phoneNumber!,
      icNumber: formData.icNumber!,
      carPlate: formData.carPlate || 'N/A',
      blockNumber: formData.blockNumber!,
      lotNumber: formData.lotNumber!,
      timestamp: Date.now()
    };
    setGeneratedQR(JSON.stringify(payload));
  };

  if (generatedQR) {
    return (
      <div className="min-h-screen bg-slate-50 p-6 flex flex-col items-center justify-center animate-fade-in">
        <div className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200">
          <div className="bg-emerald-600 p-6 text-white text-center">
            <CheckCircle className="w-12 h-12 mx-auto mb-2" />
            <h2 className="text-2xl font-bold">Access Pass Generated</h2>
            <p className="opacity-90 text-sm mt-1">Valid for 24 Hours</p>
          </div>

          <div className="p-8 flex flex-col items-center">
            <div className="bg-white p-4 rounded-xl border-2 border-slate-100 shadow-inner">
              <QRCodeSVG value={generatedQR} size={220} level="H" includeMargin={true} />
            </div>

            <p className="mt-6 text-slate-500 text-center text-sm px-4">
              Please present this QR code to the security guard at the main entrance.
            </p>

            <div className="mt-8 w-full space-y-3">
               <button 
                onClick={() => window.print()}
                className="w-full flex items-center justify-center gap-2 bg-slate-900 text-white py-3 rounded-xl font-semibold hover:bg-slate-800 transition-colors"
              >
                <Download size={18} />
                Save / Print
              </button>
              <button 
                onClick={() => setGeneratedQR(null)}
                className="w-full py-3 text-slate-600 hover:text-slate-900 font-medium"
              >
                Generate New Pass
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md mx-auto">
        <button 
          onClick={onBack} 
          className="flex items-center text-slate-500 hover:text-slate-900 mb-6 transition-colors"
        >
          <ArrowLeft className="mr-2" size={20} />
          Back to Home
        </button>

        <div className="bg-white rounded-2xl shadow-lg p-8 border border-slate-100">
          <div className="mb-8">
            <h1 className="text-2xl font-bold text-slate-900">Visitor Registration</h1>
            <p className="text-slate-500 mt-2">Please fill in your details to generate an entry pass.</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Full Name (as per IC)</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="text-slate-400" size={18} />
                </div>
                <input
                  required
                  name="fullName"
                  type="text"
                  value={formData.fullName}
                  onChange={handleChange}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all"
                  placeholder="Ali Bin Abu"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">IC Number (Digits Only)</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <CreditCard className="text-slate-400" size={18} />
                </div>
                <input
                  required
                  name="icNumber"
                  type="text"
                  inputMode="numeric"
                  value={formData.icNumber}
                  onChange={handleChange}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all"
                  placeholder="e.g. 901020105555"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Car Plate Number</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Car className="text-slate-400" size={18} />
                </div>
                <input
                  required
                  name="carPlate"
                  type="text"
                  value={formData.carPlate}
                  onChange={handleChange}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all"
                  placeholder="ABC 1234"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Phone Number</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Phone className="text-slate-400" size={18} />
                </div>
                <input
                  required
                  name="phoneNumber"
                  type="tel"
                  value={formData.phoneNumber}
                  onChange={handleChange}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all"
                  placeholder="012-3456789"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Block</label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Building className="text-slate-400" size={18} />
                  </div>
                  <input
                    required
                    name="blockNumber"
                    type="text"
                    value={formData.blockNumber}
                    onChange={handleChange}
                    className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all"
                    placeholder="A"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Lot / Unit</label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <MapPin className="text-slate-400" size={18} />
                  </div>
                  <input
                    required
                    name="lotNumber"
                    type="text"
                    value={formData.lotNumber}
                    onChange={handleChange}
                    className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all"
                    placeholder="10-05"
                  />
                </div>
              </div>
            </div>

            <button
              type="submit"
              className="w-full bg-emerald-600 text-white font-bold py-3 px-4 rounded-xl hover:bg-emerald-700 focus:ring-4 focus:ring-emerald-500/20 transition-all shadow-lg shadow-emerald-600/20 mt-4"
            >
              Generate Pass
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default VisitorForm;
```

## components/GuardDashboard.tsx

Updated the dashboard to display the new Car Plate field during scanning and when logging the entry.

```tsx
import React, { useState, useEffect } from 'react';
import { Scan, ShieldCheck, ShieldAlert, Clock, ArrowLeft, Loader2, CheckSquare, FileText, Sparkles, Car } from 'lucide-react';
import QRScanner from './QRScanner';
import VisitorLogs from './VisitorLogs';
import { VisitorData, SecurityLog } from '../types';
import { logVisitorEntry } from '../services/gemini';
import { saveLog, getLogs } from '../services/storage';

interface GuardDashboardProps {
  onBack: () => void;
}

type DashboardView = 'HOME' | 'SCANNER' | 'LOGS';

const formatLogContent = (text: string) => {
  if (!text) return null;
  const cleanText = text.replace(/^"|"$/g, ''); 
  return cleanText.split(/(\*\*.*?\*\*)/g).map((part, index) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <span key={index} className="font-semibold text-emerald-400">{part.slice(2, -2)}</span>;
    }
    return <span key={index} className="text-slate-300">{part}</span>;
  });
};

const GuardDashboard: React.FC<GuardDashboardProps> = ({ onBack }) => {
  const [view, setView] = useState<DashboardView>('HOME');
  const [scannedData, setScannedData] = useState<VisitorData | null>(null);
  const [status, setStatus] = useState<'IDLE' | 'VALID' | 'EXPIRED' | 'INVALID'>('IDLE');
  const [isLogging, setIsLogging] = useState(false);
  const [aiLog, setAiLog] = useState<string | null>(null);
  const [todayCount, setTodayCount] = useState(0);

  useEffect(() => {
    if (view === 'HOME') {
      const logs = getLogs();
      const today = new Date().setHours(0,0,0,0);
      const count = logs.filter(l => new Date(l.checkInTime).setHours(0,0,0,0) === today).length;
      setTodayCount(count);
    }
  }, [view]);

  const handleScan = (data: string) => {
    setView('HOME');
    try {
      const visitor: VisitorData = JSON.parse(data);
      setScannedData(visitor);

      const now = Date.now();
      const twentyFourHours = 24 * 60 * 60 * 1000;

      if (now - visitor.timestamp > twentyFourHours) {
        setStatus('EXPIRED');
      } else {
        setStatus('VALID');
      }
    } catch (e) {
      setStatus('INVALID');
    }
  };

  const handleCheckIn = async () => {
    if (!scannedData) return;
    setIsLogging(true);

    // 1. Generate AI Log
    const logText = await logVisitorEntry(scannedData, status);
    setAiLog(logText);

    // 2. Save to Storage
    const newLogEntry: SecurityLog = {
      id: crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(),
      visitorName: scannedData.fullName,
      icNumber: scannedData.icNumber,
      carPlate: scannedData.carPlate,
      destination: `Blk ${scannedData.blockNumber} - ${scannedData.lotNumber}`,
      checkInTime: new Date().toISOString(),
      status: status === 'VALID' ? 'GRANTED' : (status === 'EXPIRED' ? 'EXPIRED' : 'DENIED'),
      aiAnalysis: logText
    };

    saveLog(newLogEntry);
    setIsLogging(false);

    // Update count immediately after saving
    setTodayCount(prev => prev + 1);
  };

  const resetScanner = () => {
    setScannedData(null);
    setStatus('IDLE');
    setAiLog(null);
    setView('SCANNER');
  };

  if (view === 'LOGS') {
    return <VisitorLogs onBack={() => setView('HOME')} />;
  }

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 p-4 sm:p-6">
      {view === 'SCANNER' && <QRScanner onScan={handleScan} onClose={() => setView('HOME')} />}

      <div className="max-w-2xl mx-auto">
        <div className="flex items-center justify-between mb-8">
          <button 
            onClick={onBack}
            className="flex items-center text-slate-400 hover:text-white transition-colors"
          >
            <ArrowLeft className="mr-2" /> Back
          </button>
          <div className="flex items-center gap-2 text-emerald-400 font-semibold">
            <ShieldCheck size={20} />
            <span>Guard Terminal</span>
          </div>
        </div>

        {!scannedData ? (
          <div className="flex flex-col gap-6">
            <div className="flex flex-col items-center justify-center h-[50vh] border-2 border-dashed border-slate-700 rounded-3xl bg-slate-800/30 p-8 text-center">
              <Scan size={64} className="text-slate-500 mb-6" />
              <h2 className="text-2xl font-bold mb-2">Visitor Check-in</h2>
              <p className="text-slate-400 max-w-xs mb-8">
                Scan visitor QR codes to verify validity and log entry.
              </p>
              <button
                onClick={() => setView('SCANNER')}
                className="bg-indigo-600 hover:bg-indigo-500 text-white px-8 py-4 rounded-xl font-bold shadow-lg shadow-indigo-600/30 transition-all flex items-center gap-3 text-lg w-full sm:w-auto justify-center"
              >
                <Scan /> Launch Scanner
              </button>
            </div>

            <button
              onClick={() => setView('LOGS')}
              className="group bg-slate-800 hover:bg-slate-700 text-slate-300 px-6 py-4 rounded-xl font-semibold border border-slate-700 transition-all flex items-center justify-between"
            >
              <div className="flex items-center gap-3">
                 <FileText size={20} className="text-emerald-500" /> 
                 <span>View Access Logs</span>
              </div>
              <div className="bg-slate-900 px-3 py-1 rounded-full text-xs font-mono text-emerald-400 border border-slate-700 group-hover:border-slate-600">
                {todayCount} Today
              </div>
            </button>
          </div>
        ) : (
          <div className="space-y-6">
            {/* Status Card */}
            <div className={`p-6 rounded-xl border-l-4 shadow-lg ${
              status === 'VALID' ? 'bg-emerald-900/20 border-emerald-500' : 
              status === 'EXPIRED' ? 'bg-amber-900/20 border-amber-500' : 'bg-red-900/20 border-red-500'
            }`}>
              <div className="flex items-start justify-between">
                <div>
                  <h3 className={`text-xl font-bold ${
                    status === 'VALID' ? 'text-emerald-400' : 
                    status === 'EXPIRED' ? 'text-amber-400' : 'text-red-400'
                  }`}>
                    {status === 'VALID' ? 'Access Granted' : status === 'EXPIRED' ? 'Pass Expired' : 'Invalid QR'}
                  </h3>
                  <p className="text-slate-400 text-sm mt-1">
                    Scanned at {new Date().toLocaleTimeString()}
                  </p>
                </div>
                {status === 'VALID' ? <CheckSquare className="text-emerald-500" size={32} /> : <ShieldAlert className="text-amber-500" size={32} />}
              </div>
            </div>

            {/* Details Card */}
            <div className="bg-slate-800 rounded-xl p-6 shadow-xl border border-slate-700">
              <h3 className="text-lg font-semibold text-white mb-4 border-b border-slate-700 pb-2">Visitor Information</h3>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="text-xs text-slate-400 uppercase tracking-wider">Full Name</label>
                  <p className="text-lg font-medium text-white">{scannedData.fullName}</p>
                </div>
                <div>
                  <label className="text-xs text-slate-400 uppercase tracking-wider">IC Number</label>
                  <p className="text-lg font-medium text-white font-mono">{scannedData.icNumber}</p>
                </div>
                <div>
                  <label className="text-xs text-slate-400 uppercase tracking-wider">Car Plate</label>
                  <p className="text-lg font-medium text-white font-mono">{scannedData.carPlate || 'N/A'}</p>
                </div>
                <div>
                  <label className="text-xs text-slate-400 uppercase tracking-wider">Destination</label>
                  <p className="text-lg font-medium text-white">Block {scannedData.blockNumber} - Unit {scannedData.lotNumber}</p>
                </div>
                <div className="md:col-span-2">
                   <label className="text-xs text-slate-400 uppercase tracking-wider">Pass Generated</label>
                   <div className="flex items-center gap-2 text-slate-300">
                      <Clock size={16} />
                      {new Date(scannedData.timestamp).toLocaleString()}
                   </div>
                </div>
              </div>
            </div>

            {/* Actions */}
            {aiLog ? (
               <div className="bg-slate-800 rounded-xl overflow-hidden shadow-xl border border-slate-700 animate-fade-in">
                  <div className="p-4 bg-slate-900 border-b border-slate-700 flex items-center gap-2">
                     <ShieldCheck size={20} className="text-emerald-400" />
                     <h3 className="font-semibold text-white">Entry Logged Successfully</h3>
                  </div>

                  <div className="p-6">
                     <div className="bg-slate-950 p-4 rounded-lg border border-slate-800 mb-6">
                       <div className="text-xs font-bold text-indigo-400 mb-2 uppercase tracking-wide flex items-center gap-1.5">
                         <Sparkles size={12} /> System Audit Trail
                       </div>
                       <p className="text-slate-400 text-sm leading-relaxed">
                         {formatLogContent(aiLog)}
                       </p>
                     </div>

                     <div className="flex gap-4">
                        <button 
                         onClick={() => setView('LOGS')}
                         className="flex-1 bg-slate-700 hover:bg-slate-600 text-white py-3 rounded-lg font-medium transition-colors"
                       >
                         View All Logs
                       </button>
                       <button 
                         onClick={resetScanner}
                         className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white py-3 rounded-lg font-medium transition-colors"
                       >
                         Scan Next
                       </button>
                     </div>
                  </div>
               </div>
            ) : (
              <div className="flex gap-4">
                <button 
                  onClick={() => setScannedData(null)}
                  className="flex-1 py-3 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl font-medium transition-colors border border-slate-700"
                >
                  Cancel
                </button>
                <button 
                  onClick={handleCheckIn}
                  disabled={status !== 'VALID' || isLogging}
                  className={`flex-1 py-3 rounded-xl font-bold transition-all shadow-lg flex items-center justify-center gap-2 ${
                    status === 'VALID' 
                      ? 'bg-emerald-600 hover:bg-emerald-500 text-white shadow-emerald-900/20' 
                      : 'bg-slate-700 text-slate-500 cursor-not-allowed'
                  }`}
                >
                  {isLogging ? <Loader2 className="animate-spin" /> : <CheckSquare />}
                  {isLogging ? 'Logging...' : 'Confirm Entry'}
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default GuardDashboard;
```

## services/gemini.ts

Updated the prompt to include the visitor's car plate in the security log.

```typescript
import { GoogleGenAI } from "@google/genai";
import { VisitorData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const logVisitorEntry = async (visitor: VisitorData, status: string): Promise<string> => {
  try {
    const prompt = `
      Create a formal, brief security log entry for a condominium visitor check-in.

      Visitor Details:
      - Name: ${visitor.fullName}
      - IC: ${visitor.icNumber} (Mask the middle digits for privacy in the log)
      - Car Plate: ${visitor.carPlate || 'N/A'}
      - Destination: Block ${visitor.blockNumber}, Lot ${visitor.lotNumber}
      - Check-in Status: ${status}
      - Time: ${new Date().toLocaleString()}

      The log should be professional and suitable for a property management audit trail. 
      Mention if the check-in is standard or if there are any noted regularities based on standard Malaysian condo protocols (just imply standard procedure was followed).
      Keep it under 50 words.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "Log entry generated successfully.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Manual Override: System offline, entry logged locally.";
  }
};
```

## components/VisitorLogs.tsx

Added the Car Plate field to the CSV export and the structured log card view.

```tsx
import React, { useEffect, useState, useMemo } from 'react';
import { ArrowLeft, Trash2, Search, FileText, CheckCircle, XCircle, Clock, Download, Filter, Calendar, ShieldAlert, MapPin, CreditCard, Sparkles, Car } from 'lucide-react';
import { SecurityLog } from '../types';
import { getLogs, clearLogs } from '../services/storage';

interface VisitorLogsProps {
  onBack: () => void;
}

const formatLogContent = (text: string) => {
  if (!text) return null;
  const cleanText = text.replace(/^"|"$/g, ''); 

  const parts = cleanText.split(/(\*\*.*?\*\*)/g);

  return parts.map((part, index) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      const content = part.slice(2, -2);
      return <span key={index} className="font-semibold text-emerald-400">{content}</span>;
    }
    return <span key={index} className="text-slate-300">{part}</span>;
  });
};

const VisitorLogs: React.FC<VisitorLogsProps> = ({ onBack }) => {
  const [logs, setLogs] = useState<SecurityLog[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'GRANTED' | 'DENIED' | 'EXPIRED'>('ALL');
  const [dateFilter, setDateFilter] = useState<'ALL' | 'TODAY'>('ALL');

  useEffect(() => {
    setLogs(getLogs());
  }, []);

  const handleClear = () => {
    if (window.confirm('Are you sure you want to clear all visitor history? This action cannot be undone.')) {
      clearLogs();
      setLogs([]);
    }
  };

  const handleExportCSV = () => {
    if (logs.length === 0) return;

    const headers = ['ID', 'Visitor Name', 'IC Number', 'Car Plate', 'Destination', 'Check-In Time', 'Status', 'AI Note'];
    const rows = logs.map(log => [
      log.id,
      `"${log.visitorName}"`, 
      `"${log.icNumber}"`,
      `"${log.carPlate || 'N/A'}"`,
      `"${log.destination}"`,
      new Date(log.checkInTime).toLocaleString(),
      log.status,
      `"${log.aiAnalysis.replace(/"/g, '""')}"`
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(r => r.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
