      aiAnalysis: logText
    };

    saveLog(newLogEntry);
    setIsLogging(false);

    // Update count immediately after saving
    setTodayCount(prev => prev + 1);
  };

  const resetScanner = () => {
    setScannedData(null);
    setStatus('IDLE');
    setAiLog(null);
    setView('SCANNER');
